#include <assert.h>
#include <notify.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <sys/wait.h>
#include <unistd.h>
extern bool ne_session_app_vpn_configs_present(void);
static const char *key="com.apple.neconfigurationchanged";
static void set_state(int token,uint64_t value,bool post)
{
    assert(notify_set_state(token,value)==NOTIFY_STATUS_OK);
    if(post)assert(notify_post(key)==NOTIFY_STATUS_OK);
}
int main(void)
{
    setbuf(stdout,NULL);int token;assert(notify_register_check(key,&token)==NOTIFY_STATUS_OK);
    uint64_t old;assert(notify_get_state(token,&old)==NOTIFY_STATUS_OK);
    set_state(token,0,true);assert(!ne_session_app_vpn_configs_present());
    set_state(token,UINT64_C(1)<<62,true);assert(ne_session_app_vpn_configs_present());
    set_state(token,0,false);assert(ne_session_app_vpn_configs_present());
    assert(notify_post(key)==NOTIFY_STATUS_OK);assert(!ne_session_app_vpn_configs_present());
    set_state(token,(UINT64_C(1)<<63)|(UINT64_C(1)<<61)|1,true);assert(!ne_session_app_vpn_configs_present());
    set_state(token,UINT64_MAX,true);assert(ne_session_app_vpn_configs_present());
    pid_t child=fork();assert(child>=0);
    if(!child){int own;assert(notify_register_check(key,&own)==NOTIFY_STATUS_OK);assert(ne_session_app_vpn_configs_present());set_state(own,0,true);assert(notify_cancel(own)==NOTIFY_STATUS_OK);_exit(0);}
    int status;assert(waitpid(child,&status,0)==child && WIFEXITED(status) && WEXITSTATUS(status)==0);
    assert(!ne_session_app_vpn_configs_present());
    set_state(token,old,true);assert(notify_cancel(token)==NOTIFY_STATUS_OK);
    puts("NE_SESSION_REAL_NOTIFY_BIT62_CACHED_POST_AND_FORK_VERIFIED");return 0;
}
